rmanecen sin determinación autorizada. No se afirma su existencia ni su ausencia. Las tres decisiones relacionadas siguen pendientes.\",\n          \"scope_refs\": [\n            \"dimension:errors\",\n            \"dimension:side_effects\"\n          ],\n          \"source_signal_refs\": [\n            \"dimension:errors\",\n            \"dimension:side_effects\",\n            \"decision:A5-DEC-002\",\n            \"decision:A5-DEC-003\",\n            \"decision:A5-DEC-004\"\n          ],\n          \"status\": \"REQUIRED\"\n        },\n        {\n          \"authority_refs\": [],\n          \"blockers\": [\n            \"A5-DEC-004\",\n            \"A5-DEC-005\"\n          ],\n          \"closure\": \"BLOCKED\",\n          \"currentness_refs\": [],\n          \"evidence_refs\": [\n            \"A6-REQ-005\",\n            \"decision:A5-DEC-004\",\n            \"decision:A5-DEC-005\",\n            \"gap:ACCEPTANCE_EVIDENCE_MISSING\"\n          ],\n          \"front_id\": \"A7-FRONT-005\",\n          \"front_kind\": \"CRITERIOS_COMPRENSION\",\n          \"reason\": \"Faltan criterios autorizados para verificar que los clientes comprenden el ahorro y lo distinguen de la cuota durante el piloto. No existen umbrales o resultados verificables suministrados. Las decisiones A5-DEC-004 y A5-DEC-005 permanecen pendientes.\",\n          \"scope_refs\": [\n            \"A6-REQ-005\"\n          ],\n          \"source_signal_refs\": [\n            \"A6-REQ-005\",\n            \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n            \"decision:A5-DEC-004\",\n            \"decision:A5-DEC-005\"\n          ],\n          \"status\": \"REQUIRED\"\n        }\n      ],\n      \"source_refs\": [\n        \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n        \"supabase://public.lf_eventos/20843\"\n      ],\n      \"unmapped_material_signals\": []\n    },\n    \"no_ready_claim\": true,\n    \"package_readiness\": \"BLOCKED\",\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"research_decision\": \"REQUIRES_DECISION\",\n    \"schema_version\": \"PROGRAMMING_CONTEXT_SNAPSHOT_V1\",\n    \"scope_front_matrix\": [\n      {\n        \"effect_on_scope\": \"BLOCKS\",\n        \"front_closure\": \"BLOCKED\",\n        \"front_id\": \"A7-FRONT-001\",\n        \"front_status\": \"REQUIRED\",\n        \"scope_id\": \"A6-REQ-001\"\n      },\n      {\n        \"effect_on_scope\": \"BLOCKS\",\n        \"front_closure\": \"BLOCKED\",\n        \"front_id\": \"A7-FRONT-001\",\n        \"front_status\": \"REQUIRED\",\n        \"scope_id\": \"dimension:functional\"\n      },\n      {\n        \"effect_on_scope\": \"BLOCKS\",\n        \"front_closure\": \"BLOCKED\",\n        \"front_id\": \"A7-FRONT-001\",\n        \"front_status\": \"REQUIRED\",\n        \"scope_id\": \"dimension:permissions\"\n      },\n      {\n        \"effect_on_scope\": \"BLOCKS\",\n        \"front_closure\": \"BLOCKED\",\n        \"front_id\": \"A7-FRONT-002\",\n        \"front_status\": \"REQUIRED\",\n        \"scope_id\": \"A6-REQ-002\"\n      },\n      {\n        \"effect_on_scope\": \"BLOCKS\",\n        \"front_closure\": \"BLOCKED\",\n        \"front_id\": \"A7-FRONT-002\",\n        \"front_status\": \"REQUIRED\",\n        \"scope_id\": \"A6-REQ-004\"\n      },\n      {\n        \"effect_on_scope\": \"BLOCKS\",\n        \"front_closure\": \"BLOCKED\",\n        \"front_id\": \"A7-FRONT-002\",\n        \"front_status\": \"REQUIRED\",\n        \"scope_id\": \"dimension:data\"\n      },\n      {\n        \"effect_on_scope\": \"BLOCKS\",\n        \"front_closure\": \"BLOCKED\",\n        \"front_id\": \"A7-FRONT-003\",\n        \"front_status\": \"REQUIRED\",\n        \"scope_id\": \"A6-REQ-003\"\n      },\n      {\n        \"effect_on_scope\": \"BLOCKS\",\n        \"front_closure\": \"BLOCKED\",\n        \"front_id\": \"A7-FRONT-003\",\n        \"front_status\": \"REQUIRED\",\n        \"scope_id\": \"dimension:state\"\n      },\n      {\n        \"effect_on_scope\": \"BLOCKS\",\n        \"front_closure\": \"BLOCKED\",\n        \"front_id\": \"A7-FRONT-004\",\n        \"front_status\": \"REQUIRED\",\n        \"scope_id\": \"dimension:errors\"\n      },\n      {\n        \"effect_on_scope\": \"BLOCKS\",\n        \"front_closure\": \"BLOCKED\",\n        \"front_id\": \"A7-FRONT-004\",\n        \"front_status\": \"REQUIRED\",\n        \"scope_id\": \"dimension:side_effects\"\n      },\n      {\n        \"effect_on_scope\": \"BLOCKS\",\n        \"front_closure\": \"BLOCKED\",\n        \"front_id\": \"A7-FRONT-005\",\n        \"front_status\": \"REQUIRED\",\n        \"scope_id\": \"A6-REQ-005\"\n      }\n    ],\n    \"scope_readiness\": [\n      {\n        \"blockers\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-003\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-001\"\n        ],\n        \"scope_id\": \"A6-REQ-001\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-002\"\n        ],\n        \"scope_id\": \"A6-REQ-002\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-003\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-003\"\n        ],\n        \"scope_id\": \"A6-REQ-003\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-002\"\n        ],\n        \"scope_id\": \"A6-REQ-004\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-004\",\n          \"A5-DEC-005\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-005\"\n        ],\n        \"scope_id\": \"A6-REQ-005\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-003\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-001\"\n        ],\n        \"scope_id\": \"dimension:functional\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-002\"\n        ],\n        \"scope_id\": \"dimension:data\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-003\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-001\"\n        ],\n        \"scope_id\": \"dimension:permissions\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-003\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-003\"\n        ],\n        \"scope_id\": \"dimension:state\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-004\"\n        ],\n        \"scope_id\": \"dimension:errors\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-004\"\n        ],\n        \"scope_id\": \"dimension:side_effects\",\n        \"status\": \"BLOCKED\"\n      }\n    ],\n    \"snapshot_statement\": \"Snapshot exclusivamente candidato, construido a partir de las salidas A7 y A8 suministradas. Contiene once scopes: cinco requisitos provisionales y seis dimensiones, vinculados mediante once relaciones a cinco frentes materiales. La contabilidad de los elementos recibidos está completa, pero los cinco frentes permanecen REQUIRED y BLOCKED. Cada scope tiene al menos un frente bloqueante, por lo que ninguno puede declararse READY. La investigación conserva REQUIRES_DECISION según A8, mientras que el paquete permanece BLOCKED por decisiones materiales pendientes, ausencia de autoridad positiva, falta de evidencia de vigencia, implementación desconocida y línea base AS-IS no suministrada. Los cinco identificadores A5 deben contrastarse primero con decisiones y reglas vigentes; solo las cuestiones materialmente no resueltas corresponderían al propietario humano. La cobertura de la entrada no demuestra cobertura completa del sistema real. No se creó una huella de cobertura auténtica: los 64 ceros son únicamente el marcador solicitado por el arnés. No se ha persistido, atestiguado, aprobado ni admitido el snapshot para programación. Tampoco se ha declarado READY, seleccionado una solución técnica o autorizado implementación.\"\n  },\n  \"categories\": [\n    {\n      \"category\": \"STALE_AUTHORITY\",\n      \"definition\": \"una autoridad citada ya no está vigente\"\n    },\n    {\n      \"category\": \"HIDDEN_INDIRECT_IMPACT\",\n      \"definition\": \"un impacto indirecto no aparece declarado\"\n    },\n    {\n      \"category\": \"INCOMPLETE_CONTEXT\",\n      \"definition\": \"falta contexto necesario para decidir\"\n    },\n    {\n      \"category\": \"CONTRADICTORY_CONTEXT\",\n      \"definition\": \"dos piezas del contexto se contradicen\"\n    },\n    {\n      \"category\": \"OMITTED_MATERIAL_FRONT\",\n      \"definition\": \"se omite un frente material\"\n    },\n    {\n      \"category\": \"READY_SCOPE_WITH_BLOCKING_FRONT\",\n      \"definition\": \"un scope aparece READY pese a tener un frente bloqueante\"\n    },\n    {\n      \"category\": \"HANDOFF_SCHEMA_DRIFT\",\n      \"definition\": \"el esquema del traspaso cambia respecto del acordado\"\n    },\n    {\n      \"category\": \"LOSSY_WORKER_PROJECTION\",\n      \"definition\": \"la proyección hacia el worker pierde información material\"\n    },\n    {\n      \"category\": \"CURRENTNESS_FALSE_INVALIDATION\",\n      \"definition\": \"se invalida como vencido algo que sigue vigente\"\n    },\n    {\n      \"category\": \"CURRENTNESS_FALSE_REUSE\",\n      \"definition\": \"se reutiliza como vigente algo vencido\"\n    },\n    {\n      \"category\": \"SECOND_ORDER_CONSUMER_FAILURE\",\n      \"definition\": \"falla un consumidor de segundo orden del resultado\"\n    }\n  ],\n  \"schema_version\": \"A11_ADVERSARIAL_INPUT_V1\"\n}","request_sha256":"0a542a147b6e2374d22fabbcc5cabe93b54ba1aa6cd1f3b35bef13452a10d5a7","run_id":"A11Q_C2-GPTN-PILOT-0001","schema":"ANALYSIS_GPT_NATIVE_PACKET_V1","stage_output_selector":"A11","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A11Q/A11Q_C2","unit":"A11"}$pkt$;
 v_m jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_stored jsonb; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp
  THEN RAISE EXCEPTION 'A11Q_C2_PACKET_IDENTITY'; END IF;
 IF encode(sha256(convert_to(v_packet#>>'{input,input_literal}','UTF8')),'hex') <> v_packet#>>'{input,input_sha256}'
  THEN RAISE EXCEPTION 'A11Q_C2_INPUT_SHA_MISMATCH'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,real_execution_receipt}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A11Q_C2_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A11Q_C2_NOT_PENDING'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A11Q_UNIT_NOT_FOUND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A11Q_C2}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A11Q_C2,packet_sha256}' <> v_packet_sha
  THEN RAISE EXCEPTION 'A11Q_C2_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units
    SET unit_metadata = v_m || jsonb_build_object('gpt_native_packets_v1',
        COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A11Q_C2',v_packet))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 v_stored := v_m#>'{gpt_native_packets_v1,A11Q_C2}';
 IF v_stored IS DISTINCT FROM v_packet THEN RAISE EXCEPTION 'A11Q_C2_PACKET_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A11Q_C2_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A11Q_C2.GPT_NATIVE_HANDOFF',
   'Frozen A11Q_C2 packet handed to GPT Native for a producer run; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object(
    'evidence_schema_version','operational-event/v2','execution_id',v_exec,
    'producer','ANALYSIS_QUAL_C2_GPT_HANDOFF_V1',
    'purpose','Hand the frozen A11Q_C2 packet to GPT Native so it can produce the stage output in its own chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,
    'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_location','supabase://programacion.engineering_plan_units/'||v_unit||'#unit_metadata.gpt_native_packets_v1.'||v_cp,
    'packet_sha256',v_packet_sha,'request_sha256',v_packet->>'request_sha256',
    'input_sha256',v_packet#>>'{input,input_sha256}','producer_mode','GPT_NATIVE',
    'evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in the same chat with ONLY the JSON object, unedited. Keep the chat link; the verifier needs the RAW JSON, the chat link and the transcript SHA-256. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured output is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt'
   THEN RAISE EXCEPTION 'A11Q_C2_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A11Q_C2_CHECKPOINTS_CHANGED'; END IF;
END
$a11q_c2_prep$;
COMMIT;
